class TaskBinding {static Object queue(int kind,int n){return switch(kind){case 0->new alternate.FixedQueue(n);case 1->new alternate.CircularQueue(n);default->new alternate.DynQueue(n);};}static void put(Object x,char c){((alternate.ICharQ)x).put(c);}static char get(Object x){return ((alternate.ICharQ)x).get();}static void transfer(Object s,Object d,int n){alternate.QueueTransfer.transfer((alternate.ICharQ)s,(alternate.ICharQ)d,n);}}
